// Generates supabase/seed.sql from src/data/seedPubs.js so the seed data has a single source.
// Usage: npm run seed:sql
import { writeFileSync } from "node:fs";
import { SEED_PUBS } from "../src/data/seedPubs.js";
import { PUB_RESEARCH } from "../src/data/pubResearch.js";
import { SEED_EVENTS } from "../src/data/seedEvents.js";

const q = value => (value == null ? "null" : `'${String(value).replace(/'/g, "''")}'`);
const arr = values => `array[${values.map(q).join(", ")}]::text[]`;

const lines = [
  "-- Generated by scripts/generate-seed-sql.mjs from src/data/seedPubs.js. Do not edit by hand.",
  "-- Safe to re-run: existing pubs and drinks are left alone; website details only fill in blanks.",
  "-- Needs migrations 0001-0005.",
  "begin;",
  ""
];

SEED_PUBS.forEach((pub, pubIndex) => {
  const research = PUB_RESEARCH[pub.id] || {};
  lines.push(
    `insert into public.pubs (id, name, address, area, lat, lng, opened_year, tags, description, website, drinks_menu_url, operator) values (${[
      q(pub.id), q(pub.name), q(pub.address), q(pub.area), pub.lat, pub.lng, pub.opened_year ?? "null", arr(pub.tags), q(pub.description),
      q(research.website), q(research.drinks_menu_url), q(research.operator)
    ].join(", ")}) on conflict (id) do update set` +
      " website = coalesce(public.pubs.website, excluded.website)," +
      " drinks_menu_url = coalesce(public.pubs.drinks_menu_url, excluded.drinks_menu_url)," +
      " operator = coalesce(public.pubs.operator, excluded.operator);"
  );
  lines.push(
    `insert into public.pub_admin (pub_id, prices_online, notes) values (${[
      q(pub.id), q(research.prices_online || "unknown"), q(research.notes || "")
    ].join(", ")}) on conflict (pub_id) do nothing;`
  );
  pub.drinks.forEach((drink, drinkIndex) => {
    // Spread seed "last updated" times over the past few weeks so the UI shows realistic ages.
    const daysAgo = 3 + ((pubIndex * 5 + drinkIndex * 3) % 35);
    const measure = drink.measure || "pint";
    // Real prices carry their source, link and date; everything else is a starting estimate.
    const source = drink.source || "seed";
    const updated = drink.updated ? `timestamptz '${drink.updated.replace("T", " ")}'` : `now() - interval '${daysAgo} days'`;
    lines.push(
      `insert into public.drinks (pub_id, name, category, measure, volume_ml, current_price, source, source_url, last_updated_at) values (${[
        q(pub.id), q(drink.name), q(drink.category), q(measure), drink.volume_ml ?? "null", drink.price.toFixed(2), q(source), q(drink.source_url), updated
      ].join(", ")}) on conflict (pub_id, name_normalized, measure) do nothing;`
    );
  });
  lines.push("");
});

lines.push("-- Researched regular events: seeded UNPUBLISHED until an admin checks them.");
SEED_EVENTS.forEach(event => {
  lines.push(
    `insert into public.events (pub_id, title, category, description, schedule, weekdays, start_time, end_time, source, source_url, is_published) values (${[
      q(event.pub_id), q(event.title), q(event.category), q(event.description), "'weekly'",
      `array[${event.weekdays.join(", ")}]::smallint[]`, q(event.start_time), q(event.end_time), "'research'", q(event.source_url), "false"
    ].join(", ")}) on conflict (pub_id, title) do nothing;`
  );
});
lines.push("");

lines.push(
  "-- One history entry per seeded drink, so trends start from the first known price.",
  "insert into public.price_reports (pub_id, drink_id, drink_name, category, measure, price, reported_at, source, source_url)",
  "select d.pub_id, d.id, d.name, d.category, d.measure, d.current_price, d.last_updated_at, d.source, d.source_url",
  "from public.drinks d",
  "where not exists (select 1 from public.price_reports r where r.drink_id = d.id);",
  "",
  "commit;",
  ""
);

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote supabase/seed.sql (${SEED_PUBS.length} pubs, ${SEED_PUBS.reduce((n, p) => n + p.drinks.length, 0)} drinks)`);
